(()=>{'use strict';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
window.openPropertyTools=()=>{const dialog=document.querySelector('#dialog'),body=document.querySelector('#dialog-content');body.innerHTML=`<h2>From lot lines to a lawn quote.</h2><p>Look up the property, confirm the grass area, then review your price.</p><form id="property-form" class="form"><label>Full property address<input name="address" required minlength="8" maxlength="250" placeholder="Street, city, state, ZIP"></label><label class="check"><input type="checkbox" name="consent" required>I confirm this service-property lookup. The address goes to RealEstateAPI.</label><p class="help">The free API server may take a minute to wake up. Preview trial: 10 lookup attempts for 14 days from first use. Failed attempts also use the allowance. Provider calls may use your RealEstateAPI plan credits. No paid add-on checkout is active.</p><button class="button primary full">Look up property & lot lines</button></form><p id="property-error" class="error" role="status"></p><div id="property-result"></div>`;dialog.showModal();document.querySelector('#property-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;document.querySelector('#property-error').textContent='';try{await MM.api({action:'list'});const r=await fetch(window.MM_PROPERTY_API+'/api/property',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+MM.session.access_token},body:JSON.stringify({address:new FormData(e.target).get('address'),confirm_provider_lookup:true}),signal:AbortSignal.timeout(120000)}),d=await r.json();if(!r.ok)throw Error(d.error||'Could not look up property');show(d);}catch(err){document.querySelector('#property-error').textContent=err.message}finally{button.disabled=false}};};
function plot(geometries){const rings=geometries.flatMap(g=>g.type==='Polygon'?g.coordinates:g.coordinates.flat()),points=rings.flat().filter(p=>Array.isArray(p)&&p.length>=2&&p.every(Number.isFinite));if(points.length<3)return '<p class="help">No renderable boundary returned. Confirm parcel access on your API plan.</p>';const minX=Math.min(...points.map(p=>p[0])),maxX=Math.max(...points.map(p=>p[0])),minY=Math.min(...points.map(p=>p[1])),maxY=Math.max(...points.map(p=>p[1])),scale=Math.min(320/(maxX-minX||1),200/(maxY-minY||1));return `<svg viewBox="0 0 360 240" style="width:100%;background:#f1f7e7;border-radius:12px" role="img" aria-label="Property parcel boundary, approximate outline without a basemap"><path d="${rings.map(r=>r.filter(p=>p.length>=2&&p.every(Number.isFinite)).map((p,i)=>(i?'L':'M')+(20+(p[0]-minX)*scale).toFixed(2)+','+(220-(p[1]-minY)*scale).toFixed(2)).join(' ')+' Z').join(' ')}" fill="#c2f600" fill-opacity=".35" stroke="#30603c" stroke-width="3" fill-rule="evenodd"/></svg><p class="help">Parcel outline only. This is not a surveyed boundary or measured lawn area.</p>`;}
function show(d){const p=d.property;document.querySelector('#property-result').innerHTML=`<h3 style="margin-top:24px">${esc(p.address)}</h3><p>Recorded lot: <b>${p.lot_sqft?Number(p.lot_sqft).toLocaleString()+' sq ft':'Not available'}</b></p><p class="help">${d.trial.remaining} trial lookups remaining · ${d.boundary_error?esc(d.boundary_error):'Property data retrieved.'}</p>${plot(p.geometries||[])}<div class="notice">Lot size includes buildings, paving, pools and other areas. Confirm the actual mowable grass before pricing.</div><form id="quote-form" class="form"><label>Confirmed mowable grass (sq ft)<input name="area" type="number" min="1" ${p.lot_sqft?'max="'+p.lot_sqft+'"':''} required></label><label>Minimum price per visit ($)<input name="minimum" type="number" min="0" step=".01" value="45" required></label><label>Price per 1,000 sq ft ($)<input name="rate" type="number" min="0" step=".01" value="8" required></label><label>Gate / access / trimming adjustment ($)<input name="adjustment" type="number" min="0" step=".01" value="0" required></label><label>Visits per year<input name="visits" type="number" min="1" max="365" value="26" required></label><label class="check"><input type="checkbox" required>I verified the grass area and access conditions.</label><button class="button primary full">Calculate owner-review estimate</button></form><div id="quote-result" role="status"></div>`;document.querySelector('#quote-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),num=n=>Number(f.get(n)),per=Math.round((Math.max(num('minimum'),num('area')/1000*num('rate'))+num('adjustment'))*100)/100,monthly=Math.round(per*num('visits')/12*100)/100;document.querySelector('#quote-result').innerHTML=`<div class="message"><strong>$${per.toFixed(2)} per visit</strong><p>$${monthly.toFixed(2)} monthly average at ${num('visits')} visits/year.</p><p class="help">Owner-review estimate only. No customer enrollment, payment or guaranteed margin. Confirm labor, fuel and other costs before approving.</p></div>`;};}
})();
